import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"How to remember everything you read (stop trying)","description":"","frontmatter":{"url":"https://x.com/thedankoe/status/2081415714636996844","title":"How to remember everything you read (stop trying)","author":"thedankoe","archived":"2026-07-30T00:00:00.000Z","handle":"@thedankoe","published":"2026-07-26T00:00:00.000Z","stats":"22414 likes · 3353 retweets · 59479 bookmarks · 11792623 views","tags":["learning","note-taking","second-brain","content-creation","self-help"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-26-@thedankoe-996844.md","filePath":"research/tweets/2026-07-26-@thedankoe-996844.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-07-26-@thedankoe-996844.md"};function r(s,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="how-to-remember-everything-you-read-stop-trying-—-thedankoe" tabindex="-1">How to remember everything you read (stop trying) — @thedankoe <a class="header-anchor" href="#how-to-remember-everything-you-read-stop-trying-—-thedankoe" aria-label="Permalink to &quot;How to remember everything you read (stop trying) — @thedankoe&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/thedankoe/status/2081415714636996844" target="_blank" rel="noreferrer">https://x.com/thedankoe/status/2081415714636996844</a><strong>作者</strong>：thedankoe（@thedankoe） <strong>發布日期</strong>：2026-07-26 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Twitter Article <strong>統計</strong>：22414 likes · 3353 retweets · 59479 bookmarks · 11792623 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><blockquote><p>If you need to remember it, it&#39;s not important. If it&#39;s important, you will remember it.</p></blockquote><p>For some reason, it&#39;s become an obsession to remember everything you read. There are hundreds of videos about it with millions of views.</p><p>People feel like if they don&#39;t retain the knowledge from what they read, they&#39;re a failure, or they wasted your time, when that&#39;s not the point of reading at all.</p><p>Why would you want to memorize every word of a book in the first place?</p><p>I know why.</p><p>You want to sound smart.</p><p>It&#39;s an unconscious status symbol for you.</p><p>You want to impress others with your articulation and intelligence, but you don&#39;t realize that sounding smart comes from understanding, not memorization, and understanding requires a much different approach to learning. It also doesn&#39;t help that schools tested you on your ability to memorize. You studied for hours just so you could pencil in the right answer. That&#39;s not how life works.</p><p>I get it.</p><p>You want to acquire knowledge so that you can make better decisions and work yourself into a more advantageous life situation with more money and power so you don&#39;t have to worry about your day-to-day survival. Everyone wants that, but memorizing facts is the least effective way to get there.</p><p>That&#39;s what we&#39;ll talk about first - how to acquire knowledge in a way that actually sticks, so you can create a better future for yourself.</p><p>Then, we&#39;ll talk about why your note-taking system, bookmarks, and even your precious &quot;second brain&quot; (the sex doll for mental masturbators) are largely useless.</p><hr><p>Skip to the rest of the article if you&#39;re allergic to self-promotion:</p><p>Speaking of second brain, we just added Library, Reader, and Highlights to Eden. Now, not only can you research creators&#39; top content and find your next viral topic (and schedule posts to be published), but you can build an interconnected library of posts, links, and ideas that Eden organizes for you - and allows you to search based on meaning rather than just keywords.</p><p>And, you can save any Substack article, X article, or YouTube video, read the transcript, and highlight so you never lose an idea.</p><p>We haven&#39;t fully started blasting Eden in public yet, but our users have been vocal about how much of a game-changer it is for creatives and creators.</p><p>Get 4 months and the Creator Bootcamp free (normally $499) here.</p><h2 id="how-to-actually-learn-anything-fast" tabindex="-1">How to actually learn anything fast <a class="header-anchor" href="#how-to-actually-learn-anything-fast" aria-label="Permalink to &quot;How to actually learn anything fast&quot;">​</a></h2><p>[圖 1]</p><p>Most people have no idea how to learn.</p><p>Because most people have no idea what the learning process is.</p><p>The reason most learning fails is that there is no negative feedback loop.</p><p>Think of it like this.</p><p>If you don&#39;t have the goal of getting in shape (and I&#39;m talking a deep intrinsically generated goal not a superficial goal you&#39;re pursuing to fit in, like a new years resolution) then a night of heavy drinking and partying won&#39;t register as a problem (negative feedback), because it doesn&#39;t impact your non-existent goal of performing on your morning run or gym session the next day. You can go to work just fine with a hangover because you don&#39;t give a shit about how well you do at your job.</p><p>Learning is a cybernetic process.</p><p>Cybernetics sounds like something relating to cyborgs, but it stems from the Greek word kybernētēs, meaning steersman or helmsman. The person who steers the ship.</p><p>The word &quot;cybernetics&quot; was chosen because the helmsman is the perfect image of a feedback system. The helmsman doesn&#39;t just point the ship in a direction once, he constantly reads the current state (wind, waves, heading), compares it against the intended course, and adjusts. In other words, the process of trial and error, and so few people have the direction that allows them to notice errors in their life.</p><p>Cybernetics illustrates the properties of intelligent systems.</p><p>[圖 2]</p><ol><li>Reference signal (the goal) – The system holds a target state.</li><li>Sensor (perception) – The system reads its current state.</li><li>Comparator (the gap) – The system computes the difference between target and current state. The difference is the error signal.</li><li>Actuator (behavior) – The system acts to reduce the error.</li></ol><p>Like how a thermostat turns on the heat when it gets too cold, or how your pancreas releases insulin when blood sugar rises.</p><p>That exposes the issue nicely.</p><p>When most people try to learn something new, they focus on content. They hoard material and try to absorb it with spaced repetition, flashcards, courses, and learning the fundamentals. They assume learning is an input process.</p><p>In reality, learning is an output process, because output demands input.</p><p>A goal creates the error signal.</p><p>The error signal creates the filter.</p><p>The filter creates relevance (most people fill their mind with noise and things they will never use).</p><p>The relevance creates retention.</p><p>A person who has been conditioned their entire life to have the nearly unconscious goal of going to school and getting a job will naturally learn and behave in that direction. The destiny they were assigned will inevitably come true.</p><p>The person who is deeply conditioned to go down the default path will not even notice money-making opportunities outside of a job, because their brain is filtering it out. The big life goals they were assigned at birth dictate their behavior and learning. They are a puppet of someone else&#39;s ideals. They are not in control of their life.</p><p>But if you consciously create your own frame, by knowing exactly what you don&#39;t want out of life and comparing it to an evolving vision of what you do want out of life, you are only then able to sense when you are off track, notice the error, correct the direction you are heading, and learn as a byproduct.</p><p>Makes sense, but what do you actually do?</p><p>Step 1) Become obsessed with a meaningful goal.</p><p>The way you become obsessed is to look at your current actions and realize where your life will end up if you don&#39;t change.</p><p>For most people, that outcome is not pretty.</p><p>Sit with that image, let it fill you with potent emotion, and redirect that emotional energy toward a better direction for your life.</p><p>Only then can you actually align the goals you pursue with the aim of your future. Only then does a useful learning process start, the opposite of schooling, where your learning is determined by the direction and goals society sets for you.</p><p>Being extreme changes your brain and enhances neuroplasticity. In my eyes, you&#39;re better off making an extreme change than making a lot of small changes.</p><p>Burn the boats. Change your life.</p><ol start="2"><li>Don&#39;t start learning.</li></ol><p>The life you want lies at the end of a series of meaningful projects.</p><p>Your mind is to be treated as a project. As is your body, relationships, and financial situation. A project is simply a structured set of goals and milestones. A project creates a frame for your learning (by filtering unimportant noise). Anything that does not directly move the project forward is not worth learning (right now), because you won&#39;t retain it anyway.</p><p>In other words, when you want to learn something new, don&#39;t start learning, take the first step toward the goal instead.</p><ol start="3"><li>Seek specific knowledge.</li></ol><blockquote><p>I ultimately think that everyone should be figuring out what it is that they uniquely do best—that aligns with who they are fundamentally, and that gives them authenticity, that brings them specific knowledge, that gives them competitive advantage, that makes them irreplaceable. And they should just lean into that. And sometimes you don&#39;t know what that is until you do it.</p></blockquote><p>– Naval</p><p>Schools teach general knowledge, or knowledge required to do a job.</p><p>They do not teach how to navigate your own path. They narrow you into one area of study, which by nature does not prepare you to direct your own work through the path of entrepreneurship - or simply doing what you want to do.</p><p>Self-education is the process of learning what&#39;s necessary to achieve self-generated goals. Again, no hoarding general knowledge to feel like you&#39;re learning.</p><p>As an example, let&#39;s say I want to learn After Effects - the animation software.</p><p>It would be stupid to go and watch a bunch of general After Effects tutorials and learn every little thing about the software.</p><p>Instead, you need a vision for the project you want to build.</p><p>You start the project with the knowledge you have, and if you don&#39;t have knowledge, then you find a specific tutorial that is as similar to the project you want to create as it can be.</p><p>Now, since you have a filter (what you want to create), most of the tutorial will be useless, but you will find one little technique that allows you to at least start the project.</p><p>You apply that and then repeat until you&#39;ve stacked so many techniques that when you go to create your next project, then the next, it becomes easier and easier.</p><p>Same with learning the guitar or an instrument.</p><p>You don&#39;t go and study music theory.</p><p>You choose a song you want to play.</p><p>Then you learn the first chord of the song. Then the second. Then the third. And eventually you learn to tune it a specific way, and you pick up little hacks that allow you to play better.</p><p>After learning a few songs, you feel as if you could then create your own simple song.</p><p>That is how you learn.</p><h2 id="the-second-subconscious-delete-your-note-taking-system" tabindex="-1">The Second Subconscious (Delete Your Note-Taking System) <a class="header-anchor" href="#the-second-subconscious-delete-your-note-taking-system" aria-label="Permalink to &quot;The Second Subconscious (Delete Your Note-Taking System)&quot;">​</a></h2><p>I&#39;ve tried all the systems before, and I loved them. I started with Roam Research, and it completely changed how I write. I built a knowledge base of potent ideas, and pulled from those every time I sat down to put words on a screen.</p><p>A few years ago, I even built Kortex, which wasn&#39;t meant to be second-brain software, but that&#39;s what it ended up being before it inevitably failed. Well, it didn&#39;t really fail, but it painfully evolved into Eden, which has become the best tool on the market to find what&#39;s trending on social media (for creators), and capture ideas from anywhere (for creatives).</p><p>So, I&#39;m not here to say that second brains are useless.</p><p>I simply think they&#39;re misused.</p><p>You bookmark and take notes just for them to never be seen again. You quite literally wasted your time thinking you were learning when you could have been actually learning, as we discussed.</p><p>In the past, people didn&#39;t have a popularized &quot;second brain&quot; that markets well. They had a commonplace book.</p><p>Marcus Aurelius&#39; book, Meditations, is essentially a private commonplace book with notes to himself and digested philosophy. It was never meant to be published.</p><p>Leonardo da Vinci filled thousands of notebook pages with sketches, observations, questions, and borrowed ideas.</p><p>Mark Twain, H.P. Lovecraft, Thomas Jefferson, Ronald Reagan, Montaigne, Rick Rubin, and many more each had some variation of this.</p><p>But there is one major difference between the everyday second brain stan and them.</p><p>Their collection of ideas were fuel for their creations.</p><p>Their inventions, writing, and music would not be what they are today, and I would go as far as saying you wouldn&#39;t even know who those famous people are if they didn&#39;t have some variation of a commonplace book.</p><p>When you create something, your subconscious spits out relevant ideas that contribute to the quality of the creation, but it&#39;s still limited in processing power, and sometimes it decides to not help you at all, leaving you in a creative rut.</p><p>A metaphor that Seneca used was to gather pollen from many flowers, then digest it into your own honey.</p><p>In modern terms, steal like an artist.</p><p>This is the antidote to writers block. You don&#39;t have ideas for your writing, content, or videos because you don&#39;t have a repository of ideas to pull from. Every single thing I&#39;ve written in this letter is from articles, videos, social posts, random ideas, and highlights I&#39;ve saved before.</p><p>I think you get it, but how do we actually build this?</p><p>How do we create a digital commonplace book, or second subconscious, that we can build throughout our lives that doesn&#39;t turn into a cluttered note-taking app where your ideas go to die?</p><p>Step 1) Choose The Right Software, Or Create Your Own AI System</p><blockquote><p>Don&#39;t get breathless about how &quot;smart&quot; AI is. It&#39;s dumber than a sack of wet hammers.</p><p>Leverage, instead, its ability to do rapid input and output for simple tasks on large datasets.</p></blockquote><p>– Devon Eriksen</p><p>Most note-taking and &quot;second brain&quot; software still require manual upkeep.</p><p>Some of them have an AI chat tacked on, which is absolutely useful, but they&#39;re missing the most useful application of them all: making it so your ideas don&#39;t disappear into the void - because your creative work depends on your ability to resurface them.</p><p>You have 2 options here.</p><p>Our goal is to have somewhere to drop ideas and easily be able to resurface the right ones for our project.</p><ul><li>Option 1 - Use a combination like Claude Code + Obsidian to store your knowledge in one place and retrieve ideas with AI</li><li>Option 2 - Use a software like MyMind or Eden, which auto-tags, categorizes, and embeds your knowledge in &quot;meaning space&quot; so it can connect seemingly unrelated ideas to birth novel insights</li></ul><p>There are plenty of tutorials on the internet for option 1. It&#39;s very popular right now because people swapped their precious collection of Notion templates for a collection of Claude skills (a fad that will fade as they all do), but here&#39;s the 80/20 of how to do it yourself:</p><ol><li>Download Obsidian and Claude</li><li>Open Claude Code or Claude Cowork and select your Obsidian vault folder on your computer as the folder you&#39;re working in</li><li>Create a &quot;save an idea&quot; skill - ask claude to create a skill that creates a note in an inbox folder with a clear title</li><li>Create a &quot;process my inbox&quot; skill - ask claude to create a skill that goes through your inbox folder, add tags, move it to the right folder, and add backlinks to other related notes within the vault</li><li>Ask Claude to help you define your taxonomy so it knows what tags/categories to use</li></ol><p>That allows you to capture ideas, notes, and knowledge into a time-tested note-taking tool.</p><p>Then, you can ask Claude at anytime to &quot;Search my vault for everything related to [idea I&#39;m writing about].&quot;</p><p>That works for finding most ideas, but good writing and creative work come from novel connections, not keyword search or the AI brainstorming synonyms to find related matches.</p><p>If you don&#39;t want to do all of that manually, then you can use a software like MyMind, which allows you to save any link or idea to one big and searchable library.</p><p>Eden does the same thing (you can capture anything fast into your library), but takes it a step further. When you save a link, like a Substack article or YouTube video, it transcribes it, and allows you to highlight it. Plus, you can integrate with Kindle to pull all previous highlights in - which are potent creative fuel.</p><p>The way MyMind and Eden differ from Obsidian and Claude is that everything you add to your library is automatically tagged, categorized, and embedded. So you can do the same search that Claude allows you to do, without wasting precious AI usage (Eden also has an MCP if you do want to build and access your knowledge base with Claude.) Plus, if you&#39;re a writer or creator, Eden has an outlier search feed where you can find what social posts are performing in your niche and save them straight to your library.</p><p>I am not entirely sure if MyMind does this, but with Eden, it also differs in that it can search based on meaning.</p><p>Obsidian can show you &quot;what&#39;s related,&quot; Eden can show you &quot;what&#39;s nearby&quot; because each idea is embedded with ~1500 numbers that act as GPS coordinates for an idea. They can be found even if they share zero of the same words. This is what allows you to just drop an idea in and forget about it, because you know you will find it exactly when you need it.</p><p>[圖 3]</p><p>It can pull up novel connections without re-searching through your entire knowledge base every time, costing hundreds of thousands of AI tokens.</p><p>You probably don&#39;t want to maintain a vector database, an embedding API, indexing scripts, re-embedding when notes change, keeping the index in sync when files are renamed or deleted, and caching so you don&#39;t re-pay for unchanged content.</p><p>All of the tools do this for free, but if you want a true &quot;second subconscious&quot; that you can research while writing, creating, or building projects - Eden may be worth trying out.</p><p>Step 2) Capture The Ideas That Best Represent Your Ideal Mind</p><p>Now that you have a place to drop ideas without worrying about organization (because you only organize things if you want to find them later, which we just solved), you don&#39;t just dump everything in their.</p><p>When AI can create anything, curation matters more than ever.</p><p>You need a curated space for ideas that spark inspiration. The opposite of an endless fire hose of noise we call a social media feed.</p><p>As a writer, creator, or someone trying to do independent work (meaning you need to build an audience by attracting them to the ideas you put out), people don&#39;t follow you for your content anymore.</p><p>There&#39;s Google, AI, and plenty of information that can be found at the click of a button.</p><p>They follow you for your point of view. Your opinion. Your interpretation. Your personality. Your story. And all of those things are downstream of the ideas that compose your worldview. The ideas you use to make sense of the world.</p><p>As an example, when I get into a conversation about the nature of reality, my mind jumps to ideas about history, integral theory, spiral dynamics, and more - because I&#39;ve deemed these the most useful lens from which I can view that conversation from. It makes the most sense out of the other ideas I&#39;ve heard that tend to fall flat.</p><p>Those are the ideas you capture.</p><p>You curate a large set of knowledge that would best represent your ideal mind.</p><p>Because that&#39;s what your fancy note-taking system was meant to be, right?</p><p>You just never got around to solidifying those ideas as a part of yourself, usually through the act of thinking, writing, and sharing in public so that you can receive feedback from the market and let the best ideas win.</p><p>How do you do this?</p><p>You read more books. You let your curiosity guide you. You reject doomscrolling and embrace curated lists of authors and thinkers who are dedicated to producing good ideas. You make time for &quot;research,&quot; because as a writer or creator, that&#39;s 80% of your job.</p><p>The rest of your job is just synthesizing that &quot;research&quot; into something that&#39;s beneficial to other people.</p><p>Step 3) Build Your Ideal Mind Through The Act Of Creation</p><p>Let&#39;s close the loop.</p><p>We have the system for capturing and retrieving knowledge.</p><p>But now we need the project to apply it too so that it doesn&#39;t go to waste.</p><p>And, we still aren&#39;t capturing specific knowledge because we don&#39;t have a reason to learn. We aren&#39;t giving our mind the frame from which it can effectively signal that ideas are important enough to capture, as we discussed.</p><p>That&#39;s the entire goal we&#39;re after, right?</p><p>We want to be smarter. We want to retain and remember what we learn. We want to sound articulate. For superficial reasons, maybe, but also because the outcome of our lives depend on the decisions that we make, and our level of smartness and ability to articulate our own value absolutely contribute positively to that.</p><p>I can&#39;t tell you what to create.</p><p>But if you&#39;re interested in writing, I can give you a part of my process that recently helped someone else.</p><p>For something like writing a Substack article, YouTube script, or X article, here&#39;s what I would do:</p><ol><li>Choose a topic.</li></ol><p>Obviously.</p><p>The best topics are the ones that lie at the intersection of performance and excitement.</p><p>Performance = topics that have already proven to do well.</p><p>You find these by saving social posts that have gone viral, or using a research tool that allows you to find outlier content and study creator&#39;s top posts.</p><p>(This article I&#39;m writing now is based on &quot;How to remember everything you read,&quot; a topic that has gone viral more times than I can count, but I applied my own contrarian perspective to it).</p><p>Excitement = topics and ideas that you want to explore more out of curiosity.</p><p>Your job is to pair the topic you want to write about (that probably wouldn&#39;t do well on social media) with a topic that has already proven do well, so that you can write about what you want and increase it&#39;s potential to actually gain traction.</p><p>That&#39;s where most beginners fail.</p><ol start="2"><li>Braindump → Outline → Draft</li></ol><p>Don&#39;t start writing yet.</p><p>Writer&#39;s don&#39;t just open one page and then expect all of the ideas to linearly fall into place.</p><p>Start with a braindump. Write down all potential ideas that could fit under the topic you&#39;re writing. Look through your notes, ideas, and links and add them inside it too.</p><p>Then, start to add some structure with an outline. Take all the ideas in your braindump and try to fit them into a general storytelling framework: Problem → Insight → Solution.</p><p>Organize ideas under each of those sections in the outline.</p><p>Then, have your outline, ideas, and library of knowledge open and ready to pull from as you string together the ideas in the form of an actual draft.</p><ol start="3"><li>Use AI to remove friction, not write for you.</li></ol><p>I&#39;ll write about my thoughts on AI writing in a future letter, but when I say &quot;don&#39;t use AI for writing,&quot; I&#39;m actually saying &quot;don&#39;t use AI to articulate your own beliefs and opinions.&quot;</p><p>Now that Substack has their AI writing estimator, people are going to start pointing out how certain accounts use AI in their writing. I&#39;ve had a few point out that some of my articles have AI writing in them.</p><p>Don&#39;t be dense.</p><p>Yes, I copy paste straight from AI when providing pure information - like explanations of Greuter&#39;s 9 stages of ego development, the same information you&#39;d get from a Google search. I&#39;m not going to waste my breath trying to rewrite it in my own words, because that doesn&#39;t need to happen. It&#39;s a disservice to myself and the reader.</p><p>I think there is value in struggling to articulate your own thoughts and beliefs, which is something the anti-AI people can&#39;t seem to do very well as they are kept narrow minded by their new religion.</p><p>When I say &quot;use AI to remove friction,&quot; I am talking about using it like you would a course or mentor or editor while you are learning the skill.</p><p>If you don&#39;t know how to structure your article, ask for a list of structures that your ideas could fit into.</p><p>If you don&#39;t know what to write next, ask for a few directions the article can go.</p><p>If you don&#39;t understand something, research it, like any writer would in the past with a less efficient method of scouring through the internet for the right information.</p><p>All in all, I trust that you have a brain.</p><p>You are ultimately the one who decides what gets published.</p><p>If it doesn&#39;t represent the values, ideas, and beliefs you want it to, then refine it until it does.</p><p>I&#39;ll leave it at that, because I have much more to say that I&#39;ll save for another letter.</p><p>– Dan</p><p>If you want to write but don&#39;t know where to start, what to write about, or anything about how to grow on social media, consider joining the bootcamp here.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：學習不是輸入記憶，而是「目標→誤差訊號→過濾器→留存」的輸出驅動循環；筆記系統的價值在於成為創作燃料，而非收藏本身。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>以控制論（cybernetics）框架學習：reference signal（目標）→ sensor（感知現狀）→ comparator（誤差）→ actuator（行動修正），沒有明確目標就沒有負回饋，學習就不會發生</li><li>「先有專案 / 目標，再學習」而非「先囤積內容再學」：目標創造 filter，filter 創造 relevance，relevance 創造 retention</li><li>筆記系統 / Second Brain 的正確用法是「commonplace book」——創作的燃料庫，而非資訊倉庫；價值在於被重新調用進創作，不在於收藏量</li><li>提及一個具體工作流：Claude Code + Obsidian，建立「save an idea」與「process my inbox」兩個 skill 來管理筆記 vault（作者稱其為會退燒的流行做法）</li><li>寫作流程：Braindump → Outline → Draft，AI 用於降低摩擦（結構建議、方向探索），而非代替表達自己的觀點</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>無具體實驗數據；主要為作者個人經驗與案例（Roam Research → Kortex → Eden 產品演進史）</li><li>提及工具：Obsidian、Claude Code/Claude Cowork、MyMind、Eden（作者自家產品，含明顯業配推廣）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>全文帶有明顯自家產品（Eden）業配性質，多處段落直接導向付費 bootcamp/訂閱推廣，內容選擇與呈現角度受商業動機影響，須折價看待</li><li>Claude Code + Obsidian 的 skill 建議（save-idea / process-inbox）與本 workspace 既有 skill 化知識管理精神有表面相似，但描述過於粗略（無 schema、無驗證閘門），不足以直接落地</li><li>核心論點（目標驅動學習、control loop）為既有教育心理學觀點的重新包裝，非原創研究，證據以個人軼事為主，無可驗證來源</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>3/10</td><td>僅有粗略的 Claude+Obsidian skill 提及，無具體可套用步驟或 config</td></tr><tr><td>B. 創新性 (20%)</td><td>4/10</td><td>控制論類比有趣，但核心「目標驅動學習」為既有觀點重包裝</td></tr><tr><td>C. 證據品質 (20%)</td><td>3/10</td><td>全文為個人經驗與軼事，無數據佐證，且夾帶明顯商業推廣</td></tr><tr><td>D. 技術深度 (15%)</td><td>2/10</td><td>非技術文章，與 workspace 技術實作無直接關聯</td></tr><tr><td>E. 泛化性 (15%)</td><td>4/10</td><td>學習方法論適用面廣，但與本 workspace（agent/harness 工程）任務性質不同</td></tr><tr><td><strong>加權總分</strong></td><td><strong>3.2/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：內容為通用學習/內容創作方法論，帶明顯商業推廣，與 workspace 核心（agent/harness 工程）關聯薄弱，僅存檔備查。</p>',187)])])}const y=t(i,[["render",r]]);export{c as __pageData,y as default};
